            UPDATE ai_mcp.tenant_tier_configs SET tier = COALESCE(NEW.tier, ai_mcp.tenant_tier_configs.tier), provider = COALESCE(NEW.provider, ai_mcp.tenant_tier_configs.provider), model_name = COALESCE(NEW.model_name, ai_mcp.tenant_tier_configs.model_name), api_key = COALESCE(NEW.api_key, ai_mcp.tenant_tier_configs.api_key), temperature = COALESCE(NEW.temperature, ai_mcp.tenant_tier_configs.temperature), max_tokens = COALESCE(NEW.max_tokens, ai_mcp.tenant_tier_configs.max_tokens), created_at = COALESCE(NEW.created_at, ai_mcp.tenant_tier_configs.created_at), updated_at = COALESCE(NEW.updated_at, ai_mcp.tenant_tier_configs.updated_at), created_by = COALESCE(NEW.created_by, ai_mcp.tenant_tier_configs.created_by), updated_by = COALESCE(NEW.updated_by, ai_mcp.tenant_tier_configs.updated_by), location_id = COALESCE(NEW.location_id, ai_mcp.tenant_tier_configs.location_id), is_active = COALESCE(NEW.is_active, ai_mcp.tenant_tier_configs.is_active), intent_type = COALESCE(NEW.intent_type, ai_mcp.tenant_tier_configs.intent_type), state_category = COALESCE(NEW.state_category, ai_mcp.tenant_tier_configs.state_category), is_on_hold = COALESCE(NEW.is_on_hold, ai_mcp.tenant_tier_configs.is_on_hold) WHERE id = OLD.id RETURNING id INTO NEW.id;
        END IF;
                RETURN NEW;
            ELSIF (TG_OP = 'DELETE') THEN
                DELETE FROM ai_mcp.tenant_tier_configs WHERE id = OLD.id;
                RETURN OLD;
            END IF;
            RETURN NULL;
        END;
        $$;


