--
-- Name: v_action_approvals; Type: VIEW; Schema: ai_mcp; Owner: -
--

CREATE VIEW ai_mcp.v_action_approvals WITH (security_invoker='on') AS
 SELECT action_type,
    completed_at,
    created_at,
    created_by,
    decided_at,
    decided_by,
    decision_note,
    description,
    id,
    intent_type,
    is_active,
    is_on_hold,
    organization_id,
    organization_display,
    parameters,
    search_vector,
    session_id,
    session_display,
    state_category,
    updated_at,
    updated_by
   FROM ( SELECT base.action_type,
            base.completed_at,
            base.created_at,
            base.created_by,
            base.decided_at,
            base.decided_by,
            base.decision_note,
            base.description,
            base.id,
            base.intent_type,
            base.is_active,
            base.is_on_hold,
            base.organization_id,
            fk_organization.name AS organization_display,
            base.parameters,
            base.search_vector,
            base.session_id,
            fk_session.title AS session_display,
            base.state_category,
            base.updated_at,
            base.updated_by
           FROM ((ai_mcp.action_approvals base
             LEFT JOIN unified.organizations fk_organization ON ((base.organization_id = fk_organization.id)))
             LEFT JOIN ai_mcp.sessions fk_session ON ((base.session_id = fk_session.id)))) base_query;


