--
-- Name: v_playbook_steps; Type: VIEW; Schema: ai_mcp; Owner: -
--

CREATE VIEW ai_mcp.v_playbook_steps WITH (security_invoker='on') AS
 SELECT created_at,
    created_by,
    dependencies,
    execution_logic,
    id,
    instruction,
    intent_type,
    is_active,
    is_auto_execute,
    is_on_hold,
    location_id,
    location_display,
    name,
    organization_id,
    organization_display,
    playbook_id,
    playbook_display,
    "position",
    required_tool_key,
    search_vector,
    state_category,
    step_key,
    updated_at,
    updated_by
   FROM ( SELECT base.created_at,
            base.created_by,
            base.dependencies,
            base.execution_logic,
            base.id,
            base.instruction,
            base.intent_type,
            base.is_active,
            base.is_auto_execute,
            base.is_on_hold,
            base.location_id,
            fk_location.name AS location_display,
            base.name,
            base.organization_id,
            fk_organization.name AS organization_display,
            base.playbook_id,
            fk_playbook.name AS playbook_display,
            base."position",
            base.required_tool_key,
            base.search_vector,
            base.state_category,
            base.step_key,
            base.updated_at,
            base.updated_by
           FROM (((ai_mcp.playbook_steps base
             LEFT JOIN identity.locations fk_location ON ((base.location_id = fk_location.id)))
             LEFT JOIN unified.organizations fk_organization ON ((base.organization_id = fk_organization.id)))
             LEFT JOIN ai_mcp.playbooks fk_playbook ON ((base.playbook_id = fk_playbook.id)))) base_query;


