   FROM ( SELECT base.created_at,
            base.created_by,
            base.description,
            base.id,
            base.intent_type,
            base.is_active,
            base.is_on_hold,
            base.location_id,
            fk_location.name AS location_display,
            base.name,
            base.organization_id,
            fk_organization.name AS organization_display,
            base.search_vector,
            base.state_category,
            base.trigger_command,
            base.updated_at,
            base.updated_by
           FROM ((ai_mcp.playbooks base
             LEFT JOIN identity.locations fk_location ON ((base.location_id = fk_location.id)))
             LEFT JOIN unified.organizations fk_organization ON ((base.organization_id = fk_organization.id)))) base_query;


