    organization_id,
    organization_display,
    provider,
    search_vector,
    state_category,
    temperature,
    tier,
    updated_at,
    updated_by
   FROM ( SELECT base.api_key,
            base.created_at,
            base.created_by,
            base.id,
            base.intent_type,
            base.is_active,
            base.is_on_hold,
            base.location_id,
            fk_location.name AS location_display,
            base.max_tokens,
            base.model_name,
            base.organization_id,
            fk_organization.name AS organization_display,
            base.provider,
            base.search_vector,
            base.state_category,
            base.temperature,
            base.tier,
            base.updated_at,
            base.updated_by
           FROM ((ai_mcp.tenant_tier_configs base
             LEFT JOIN identity.locations fk_location ON ((base.location_id = fk_location.id)))
             LEFT JOIN unified.organizations fk_organization ON ((base.organization_id = fk_organization.id)))) base_query;


